onClick:
{{ (async () => { try {
 const kind=selCompanyDonorContactKind.selectedOptionValue;
 const id=selCompanyDonorContactToArchive.selectedOptionValue;
 const reason=inpCompanyDonorContactReason.text?.trim() || (kind==='address' ? inpCompanyAddressReason.text?.trim() : '');
 if(!id || !reason) {showAlert('Select a contact and enter a reason.','warning');return;}
 if(kind==='address') {
   const r=await qArchiveCompanyDonorAddress.run({id,reason});
   if(!r?.[0]?.archived) throw new Error('Address was not archived.');
   await Promise.all([qCompanyDonorAddresses.run(),qCompanyContacts.run()]);
 } else {
   const entry=(qCompanyDonorContacts.data||[]).find(c=>c.contact_id===id);
   if(!entry || entry.contact_kind!==kind) throw new Error('Select a matching contact.');
   const r=await qArchiveCompanyDonorContact.run({kind,id,reason});
   if(!r?.[0]?.archived) throw new Error('Contact was not archived.');
   await Promise.all([qCompanyDonorContacts.run(),qCompanyContacts.run(),qCompanyProfile.run()]);
 }
 showAlert('Contributor contact archived.','success');
} catch(e) {showAlert('Contact archive failed: '+(e?.message||e),'error');} })() }}
